insert into practice_exercises (id, subject_name, level, title, source) values
  ('ada6e0f1-7230-4926-af13-3a371f9eb524', $$Natuurkunde$$, $$HAVO$$, $$Schip uit koers$$, $$HAVO Natuurkunde 2024-I$$),
  ('fb65e46c-caca-42eb-906f-cb680c7eaec8', $$Natuurkunde$$, $$HAVO$$, $$Kampeerbrander op hout$$, $$HAVO Natuurkunde 2024-I$$),
  ('a811a389-39db-49d1-a0d7-ad68a868b309', $$Natuurkunde$$, $$HAVO$$, $$Falcon heavy$$, $$HAVO Natuurkunde 2024-I$$),
  ('0ef50c0c-d8c6-43a6-ab55-3ec1daa6f9b2', $$Natuurkunde$$, $$HAVO$$, $$Sarcoïde$$, $$HAVO Natuurkunde 2024-I$$),
  ('612eecba-d994-4d18-a970-79b925512fc3', $$Natuurkunde$$, $$HAVO$$, $$Infrasone trillingen$$, $$HAVO Natuurkunde 2024-I$$);

insert into practice_context_blocks (id, exercise_id, label, image_url, image_width, text_content, block_type) values
  ('1e4f0e11-9508-419b-8610-a881b5c1859a', 'ada6e0f1-7230-4926-af13-3a371f9eb524', $$figuur 1 — containerschip op de oever van de Schelde; figuur 2 — tabel gegevens containerschip$$, $$natuurkunde-havo-2024-i-schip-uit-koers-context1.png$$, 502, $$In 2017 liep een groot containerschip op de oever van de Schelde. Een onderzoeker deed onderzoek naar dit ongeluk. Hij zag dat het schip over een afstand van 50% van zijn lengte op de oever was geschoven. Zie figuur 1. Op internet zijn de gegevens van het schip te vinden. Zie figuur 2.

figuur 1: foto van het containerschip dat met zijn voorkant op de oever van de Schelde is gelopen, met sleepboten ernaast en toeschouwers op de dijk.

figuur 2: tabel gegevens containerschip — massa 1,55·10⁵ ton; lengte 366 m; maximaal vermogen 7,2·10⁷ W; maximale snelheid 46 km h⁻¹.$$, 'inline'),
  ('d2474d1f-7b36-4a76-be70-3ec462eafdd3', 'ada6e0f1-7230-4926-af13-3a371f9eb524', $$snelheid van het schip vóór het ongeluk (7,1 m s⁻¹) en de berekende wrijvingskracht (2,1·10⁷ N)$$, $$natuurkunde-havo-2024-i-schip-uit-koers-context2.png$$, 502, $$Van ieder schip wordt elke 2 minuten de positie bijgehouden. Met deze informatie bepaalde de onderzoeker de snelheid van het schip voor het ongeluk. Die bleek 7,1 m s⁻¹ te zijn. Hij ging ervan uit dat de wrijvingskracht op het schip tijdens het vastlopen op de oever constant was. Hij berekende dat die wrijvingskracht 2,1·10⁷ N was.$$, 'inline'),
  ('0ecb8020-3e61-4029-b72c-aa83834ad5a0', 'ada6e0f1-7230-4926-af13-3a371f9eb524', $$conclusie van de onderzoeker: het schip kon met de eigen motor niet loskomen$$, $$natuurkunde-havo-2024-i-schip-uit-koers-context3.png$$, 502, $$Met de gegevens uit figuur 2 kan de maximale kracht van de motor berekend worden. De onderzoeker concludeerde uit deze berekening dat de wrijvingskracht te groot was en het schip met de eigen motor niet los kon komen van de oever.$$, 'inline'),
  ('01214dc2-8664-4750-ab6e-cbfeb8421146', 'ada6e0f1-7230-4926-af13-3a371f9eb524', $$figuur 3 — duwboten duwen het schip om draaipunt D; het schip als hefboom$$, $$natuurkunde-havo-2024-i-schip-uit-koers-context4.png$$, 502, $$Er werden duwboten ingezet om het schip los te duwen van de oever. Zie figuur 3. De duwboten duwden eerst het schip aan de achterkant opzij. Het schip is hierbij als hefboom te beschouwen. Om 19.00 uur begonnen de duwboten te duwen, het schip lag toen nog stil. Een paar minuten later begon het schip om een punt te draaien dat met D is aangegeven.

figuur 3: drie bovenaanzichten op ruitjespapier van het schip op de tijdstippen 19.00, 19.06 en 19.09 uur; het schip draait steeds verder om het punt D aan de voorkant, terwijl een groep duwboten aan de achterkant duwt.$$, 'inline'),
  ('3465e480-f9a7-4434-8648-47f34a263217', 'ada6e0f1-7230-4926-af13-3a371f9eb524', $$aangrijpingspunt W van Fw en aangrijpingspunt B van Fduwboten in de figuren op de uitwerkbijlage$$, $$natuurkunde-havo-2024-i-schip-uit-koers-context5.png$$, 502, $$Op de uitwerkbijlage is de situatie van 19.00 uur, zoals getekend in figuur 3, vergroot weergegeven. In de figuren op de uitwerkbijlage zijn het aangrijpingspunt W van de wrijvingskracht Fw en het aangrijpingspunt B van de totale duwkracht Fduwboten weergegeven.$$, 'inline'),
  ('4f913bef-fb79-4937-be47-39d1cb78ef3c', 'ada6e0f1-7230-4926-af13-3a371f9eb524', $$uitwerkbijlage vraag 3 — twee vergrote bovenaanzichten van het schip om 19.00 uur met D, W en B$$, $$natuurkunde-havo-2024-i-schip-uit-koers-uitwerkbijlage-vraag3.png$$, 502, $$Uitwerkbijlage vraag 3: Teken in de figuren de armen van Fw en Fduwboten. Onder de kopjes Arm van Fw: en Arm van Fduwboten: staan twee identieke vergrote bovenaanzichten van het schip om 19.00 uur, met het draaipunt D aan de voorkant, het aangrijpingspunt W van de wrijvingskracht midden op het schip en het aangrijpingspunt B van de totale duwkracht bij de duwboten aan de achterkant.

Daaronder: Leg met behulp van de hefboomwet uit of om 19.00 uur de totale duwkracht Fduwboten groter was dan Fw, kleiner was dan Fw of even groot was als Fw. Antwoord: met invulregels.$$, 'uitwerkbijlage'),
  ('fb5863f2-b8e3-483d-9263-b3e96fc5cf16', 'ada6e0f1-7230-4926-af13-3a371f9eb524', $$figuur 4 — normaalkracht en opwaartse kracht op het vastgelopen schip$$, $$natuurkunde-havo-2024-i-schip-uit-koers-context6.png$$, 502, $$Om het schip los te duwen, moesten de duwboten de wrijvingskracht tussen het schip en de oever overwinnen. Deze wrijvingskracht is evenredig met de normaalkracht van de oever op het schip.
Behalve de normaalkracht werkte er ook een opwaartse kracht van het water op het schip. Zie schematisch en niet op schaal weergegeven in figuur 4.
Hoe dieper een schip in het water ligt, hoe groter deze opwaartse kracht is.

figuur 4: schematische dwarsdoorsnede van het schip dat deels in het water ligt en met de voorkant op de oever; twee omhoog gerichte pijlen geven Fnormaal (van de oever) en Fopwaarts (van het water) aan; onderin zijn het water en de oplopende oever aangegeven.$$, 'inline'),
  ('ab9864e9-033e-4342-9e71-4f2db621e633', 'ada6e0f1-7230-4926-af13-3a371f9eb524', $$opkomende vloed: het water in de Schelde begon te stijgen; op de uitwerkbijlage staat een tabel$$, $$natuurkunde-havo-2024-i-schip-uit-koers-context7.png$$, 502, $$Tijdens opkomende vloed (hoogwater) begon het water in de Schelde te stijgen.

Op de uitwerkbijlage staat een tabel.$$, 'inline'),
  ('d3886ec0-11c3-4c3a-80bf-e9db8fc5e3b0', 'ada6e0f1-7230-4926-af13-3a371f9eb524', $$uitwerkbijlage vraag 4 — tabel met drie krachten om het juiste antwoord te omcirkelen$$, $$natuurkunde-havo-2024-i-schip-uit-koers-uitwerkbijlage-vraag4.png$$, 502, $$Uitwerkbijlage vraag 4: Omcirkel in de tabel wat er gebeurde tijdens het stijgen van het water. De tabel heeft drie rijen, telkens met de keuze werd kleiner / bleef gelijk / werd groter:
− De zwaartekracht op het schip
− De normaalkracht van de oever op het schip
− De kracht die de duwboten moesten uitoefenen om de wrijvingskracht te overwinnen$$, 'uitwerkbijlage'),
  ('48c96e66-f9e5-4d57-bbba-e0df33e622b1', 'fb65e46c-caca-42eb-906f-cb680c7eaec8', $$figuur 1 — kampeerbrander met gasblikje$$, $$natuurkunde-havo-2024-i-kampeerbrander-op-hout-context1.png$$, 502, $$Tijdens een kampeervakantie wordt vaak gekookt op een brander met een gasblikje. Zie figuur 1.

figuur 1: foto van een pannetje op een kleine kampeerbrander die op een gasblikje is geschroefd; het geheel staat op een boomstronk.$$, 'inline'),
  ('dcc3c749-ddc3-49b6-bb20-3819b6714f59', 'fb65e46c-caca-42eb-906f-cb680c7eaec8', $$programma van eisen voor de houtbrander: rendement hoger dan 40%, 5,0 V, zichtbare indicatie, volledig opladen$$, $$natuurkunde-havo-2024-i-kampeerbrander-op-hout-context2.png$$, 502, $$Omdat gasblikjes niet overal verkrijgbaar zijn, willen Jos en Martijn voor hun profielwerkstuk een brander ontwerpen die op hout werkt. Met deze brander moet ook een telefoon opgeladen kunnen worden.
Ze stellen een programma van eisen op waar hun brander aan moet voldoen.

Enkele eisen zijn:
1 Het rendement voor water koken moet hoger zijn dan 40%.
2 De brander moet een elektrische spanning kunnen opwekken van 5,0 V voor het opladen van een telefoon.
3 Er moet zichtbaar gemaakt worden of de spanning hoog genoeg is om de telefoon op te laden.
4 De telefoon moet volledig kunnen opladen tijdens het koken van een maaltijd.$$, 'inline'),
  ('226f9bdb-b70f-4b1a-8682-0908595ec0bb', 'fb65e46c-caca-42eb-906f-cb680c7eaec8', $$meting: 400 gram water van 10 °C aan de kook brengen kost 18 gram hout$$, $$natuurkunde-havo-2024-i-kampeerbrander-op-hout-context3.png$$, 502, $$Ze bouwen een brander die hout verbrandt en koken daarmee water om de eerste eis te controleren. Om 400 gram water van 10 °C aan de kook te brengen, hebben ze 18 gram hout nodig.$$, 'inline'),
  ('9ad68b97-5385-4ba8-9602-0b43d5f21aa4', 'fb65e46c-caca-42eb-906f-cb680c7eaec8', $$figuur 2 — peltier-element met warmtegeleiders tussen vuur en ventilator$$, $$natuurkunde-havo-2024-i-kampeerbrander-op-hout-context4.png$$, 502, $$Als spanningsbron gebruiken ze een zogenaamd peltier-element. Een peltier-element levert een elektrische spanning Upelt als er een temperatuurverschil is tussen de twee zijden van het element. Jos en Martijn verwarmen de ene kant met het vuur en koelen de andere kant met een ventilator. Aan beide zijdes van het peltier-element zijn warmtegeleiders van metaal bevestigd. Zie figuur 2.

figuur 2: schematische tekening van een peltier-element met aan beide kanten een gelamelleerde warmtegeleider; links de verwarmde zijde boven een vuur, rechts de gekoelde zijde met een ventilator; de plus- en de minpool zijn via een stroomkring met de ventilator verbonden, met de spanning U aangegeven.$$, 'inline'),
  ('4302d215-1e3f-4ba1-9a2a-2659ac8a08ad', 'fb65e46c-caca-42eb-906f-cb680c7eaec8', $$eis aan de warmtegeleiders: zo snel mogelijk warmte geleiden$$, $$natuurkunde-havo-2024-i-kampeerbrander-op-hout-context5.png$$, 502, $$De warmtegeleiders moeten zo snel mogelijk warmte geleiden naar en van het peltier-element.$$, 'inline'),
  ('a734c20c-f7f0-4afc-96c4-2eae6133d3f6', 'fb65e46c-caca-42eb-906f-cb680c7eaec8', $$formule Upelt = C·ΔT met de betekenis van de symbolen$$, $$natuurkunde-havo-2024-i-kampeerbrander-op-hout-context6.png$$, 502, $$De spanning Upelt is afhankelijk van het temperatuurverschil tussen beide zijdes van het element. Bij benadering geldt:

Upelt = C·ΔT

Hierin is:
− Upelt   de opgewekte spanning;
− C   een constante;
− ΔT   het temperatuurverschil.$$, 'inline'),
  ('46531dd3-f257-48c7-b5fb-d79ecb8de874', 'fb65e46c-caca-42eb-906f-cb680c7eaec8', $$meting: 160 °C en 63 °C leveren Upelt = 2,8 V, terwijl 5,0 V nodig is$$, $$natuurkunde-havo-2024-i-kampeerbrander-op-hout-context7.png$$, 502, $$Jos en Martijn meten de temperatuur aan beide zijdes van het peltier-element. Deze is 160 °C voor de verwarmde zijde en 63 °C voor de gekoelde zijde. Het peltier-element levert dan een spanning Upelt van 2,8 V. Om hun telefoon te kunnen opladen, is echter een spanning van 5,0 V nodig.$$, 'inline'),
  ('1929fd54-76d4-4c5e-bfd1-ded41498ce95', 'fb65e46c-caca-42eb-906f-cb680c7eaec8', $$figuur 3 — led-schakeling met weerstand R₁ op het peltier-element; figuur 4 — (I,U)-diagram van de led$$, $$natuurkunde-havo-2024-i-kampeerbrander-op-hout-context8.png$$, 502, $$Ze voeren de spanning Upelt op door het vuur heter te stoken.
Jos en Martijn willen kunnen zien of de spanning al hoog genoeg is om de telefoonaccu op te laden (de derde ontwerpeis). Ze sluiten daarom een led-schakeling aan op het peltier-element. De led-schakeling bestaat uit een led en een weerstand R₁. Het peltier-element werkt dus als voedingsbron. Zie figuur 3.

figuur 3: schakelschema met de spanningsbron Upelt in serie met de weerstand R₁ en een led.

figuur 4: (I,U)-diagram van de led met I in mA (0 tot 50) tegen Uled in V (0 tot ruim 2); de stroomsterkte blijft tot ongeveer 1,4 V vrijwel nul en loopt daarna steeds steiler op; bij ongeveer 2,1 V staat een kruisje met het label defect.$$, 'inline'),
  ('fb71a6ad-4b36-4eb5-9b72-a4d9a8bb4fe2', 'fb65e46c-caca-42eb-906f-cb680c7eaec8', $$de led gaat licht geven bij Uled = 1,5 V en dat moet gebeuren bij Upelt = 5,0 V$$, $$natuurkunde-havo-2024-i-kampeerbrander-op-hout-context9.png$$, 502, $$In figuur 4 is het (I,U)-diagram van deze led weergegeven. Jos en Martijn zien dat de led licht gaat geven bij een spanning Uled van 1,5 V.
De led moet licht gaan geven bij een spanning Upelt van 5,0 V.$$, 'inline'),
  ('15ccb2a3-de50-44bf-8dfb-cdf6718b3602', 'fb65e46c-caca-42eb-906f-cb680c7eaec8', $$parallelschakeling van ventilator, led-schakeling en acculader; 0,41 A totaal, 0,30 A door ventilator en led, accu 2,6 Ah$$, $$natuurkunde-havo-2024-i-kampeerbrander-op-hout-context10.png$$, 502, $$Op het peltier-element sluiten ze nu de ventilator, de led-schakeling en een lader voor een telefoonaccu parallel aan elkaar aan. Ze houden het peltier-element op temperatuur zodanig dat het 5,0 V blijft leveren. Ze meten dat het peltier-element een stroomsterkte van 0,41 A levert. Door de ventilator en de led-schakeling samen loopt een totale stroom van 0,30 A. De telefoonaccu heeft een capaciteit van 2,6 Ah.$$, 'inline'),
  ('658df2b7-d0b9-43c3-a66e-f31bdcbb02bb', 'a811a389-39db-49d1-a0d7-ad68a868b309', $$figuur 1 — lancering van de Falcon 9 heavy; figuur 2 — bovenaanzicht van het testtraject (lancering, parkeerbaan, baan naar Mars)$$, $$natuurkunde-havo-2024-i-falcon-heavy-context1.png$$, 502, $$In februari 2018 is de Falcon 9 heavy (kortweg F9h) getest. Dit is een raket die naar Mars moet reizen. Zie figuur 1.

Het bovenaanzicht van het testtraject is schematisch en niet op schaal weergegeven in figuur 2. F9h werd gelanceerd (I) richting een baan om de aarde. Daar aangekomen werd de raket tijdelijk geparkeerd in deze baan om de aarde, de zogenaamde parkeerbaan (II). Daarna vervolgde hij zijn weg verder richting Mars (III).

figuur 1: foto van de lancering van de Falcon 9 heavy vanaf het lanceerplatform.

figuur 2: bovenaanzicht met de aarde en de aardas in het midden en daaromheen een cirkelvormige parkeerbaan II; een gestippelde lijn I loopt vanaf het aardoppervlak naar die baan en een gestippelde lijn III loopt vanaf de baan verder richting Mars.$$, 'inline'),
  ('48275c20-b70d-46dd-b1d8-312c78d7d3b2', 'a811a389-39db-49d1-a0d7-ad68a868b309', $$I Lancering — het lanceerplatform heeft zelf een snelheid vL doordat de aarde om de aardas draait$$, $$natuurkunde-havo-2024-i-falcon-heavy-context2.png$$, 502, $$I Lancering
Om in de parkeerbaan te komen, moest de raket brandstof verbranden om voldoende kinetische energie en zwaarte-energie te krijgen. De benodigde zwaarte-energie is niet afhankelijk van de plek waar de raket vanaf aarde gelanceerd werd. De benodigde kinetische energie is wel afhankelijk van de plek van lancering. Omdat de aarde om de aardas draait, heeft het lanceerplatform zelf een snelheid vL. Hierdoor had de raket al voor de lancering kinetische energie.$$, 'inline'),
  ('bf109796-de5e-407e-8b6b-b9fc0c53562c', 'a811a389-39db-49d1-a0d7-ad68a868b309', $$figuur 3 — (v,t)-diagram van de eerste minuten van de beweging van F9h$$, $$natuurkunde-havo-2024-i-falcon-heavy-context3.png$$, 502, $$Van de eerste minuten van de beweging van F9h is een (v,t)-diagram gemaakt. Zie figuur 3.

figuur 3: (v,t)-diagram op millimeterpapier met v in km h⁻¹ (0 tot 20,0·10³) tegen t in s (0 tot 400); de grafiek loopt vanuit de oorsprong steeds steiler omhoog tot ongeveer 9,5·10³ km h⁻¹ rond t = 180 s, vlakt daar korte tijd af en stijgt daarna weer vrijwel rechtlijnig tot ongeveer 17·10³ km h⁻¹ bij t = 400 s.$$, 'inline'),
  ('def0340f-bc3e-47f3-b9fd-4fc5c3fdea96', 'a811a389-39db-49d1-a0d7-ad68a868b309', $$hulpmotoren na ruim 3 minuten uitgeschakeld; figuur 3 staat ook op de uitwerkbijlage$$, $$natuurkunde-havo-2024-i-falcon-heavy-context4.png$$, 502, $$De raket gebruikte een hoofdmotor en extra hulpmotoren. Na ruim 3 minuten werden de hulpmotoren uitgeschakeld en bleef alleen de hoofdmotor van de raket werken. Figuur 3 staat ook op de uitwerkbijlage.$$, 'inline'),
  ('de883ff9-92f1-4dea-85f6-d6e2e54646c7', 'a811a389-39db-49d1-a0d7-ad68a868b309', $$uitwerkbijlage vraag 12 — vergroot (v,t)-diagram van figuur 3 om de raaklijn op t = 180 s in te tekenen$$, $$natuurkunde-havo-2024-i-falcon-heavy-uitwerkbijlage-vraag12.png$$, 502, $$Uitwerkbijlage vraag 12: een vergrote versie van figuur 3, het (v,t)-diagram met v in km h⁻¹ (0 tot 20,0·10³) tegen t in s (0 tot 400), waarin de raaklijn op t = 180 s getekend kan worden. Daaronder staat Bepaling: met invulregels voor het antwoord.$$, 'uitwerkbijlage'),
  ('ef1248a4-e11c-4d38-a495-49625698971a', 'a811a389-39db-49d1-a0d7-ad68a868b309', $$II Parkeerbaan — figuur 4: (h,t)-diagram van de hoogte van F9h boven het aardoppervlak$$, $$natuurkunde-havo-2024-i-falcon-heavy-context5.png$$, 502, $$II Parkeerbaan
In figuur 4 is in een (h,t)-diagram de hoogte van F9h boven het aardoppervlak uitgezet tegen de tijd.

figuur 4: (h,t)-diagram op millimeterpapier met h in km (0 tot 200) tegen t in s (0 tot 600); de hoogte neemt eerst steeds sneller toe, buigt daarna af en wordt vanaf ongeveer t = 480 s constant op ongeveer 180 km.$$, 'inline'),
  ('c76f7d03-2b35-4250-a90e-f817c5825619', 'a811a389-39db-49d1-a0d7-ad68a868b309', $$F9h bereikte de cirkelvormige parkeerbaan ongeveer acht minuten na de lancering$$, $$natuurkunde-havo-2024-i-falcon-heavy-context6.png$$, 502, $$Ongeveer acht minuten na de lancering bereikte F9h de cirkelvormige parkeerbaan.$$, 'inline'),
  ('9f6211a2-bd8e-4558-8de7-94a19173db75', 'a811a389-39db-49d1-a0d7-ad68a868b309', $$III Op weg naar Mars — figuur 5: zijaanzicht met waarnemer W, de posities van foto 1 en foto 2, de afstand s, Δh en Δx$$, $$natuurkunde-havo-2024-i-falcon-heavy-context7.png$$, 502, $$III Op weg naar Mars
Na een tijd verliet F9h de parkeerbaan en vervolgde de raket de reis naar Mars. Aangenomen wordt dat de snelheid van F9h in dit traject constant was en anders dan de snelheid van F9h in de parkeerbaan. Tijdens een deel van de vlucht werd F9h door een waarnemer W twee keer gefotografeerd. Het zijaanzicht van de baan is schematisch en niet op schaal weergegeven in figuur 5.

figuur 5: schematisch zijaanzicht met links het aardoppervlak en daarop de waarnemer W; vanuit W lopen twee gestippelde zichtlijnen naar de posities 1 en 2 op de rechte baan naar Mars; tussen de posities 1 en 2 is de afgelegde afstand s aangegeven, samen met de rechthoekszijden Δh (horizontaal) en Δx (verticaal) van de bijbehorende rechthoekige driehoek.$$, 'inline'),
  ('e84b5281-d9d2-46b0-bd66-8d5293f43d35', 'a811a389-39db-49d1-a0d7-ad68a868b309', $$gegevens voor de afstand s: Δh = 9,21·10⁶ m, Δx = 4,38·10⁶ m en een tijd van 20,0 minuten$$, $$natuurkunde-havo-2024-i-falcon-heavy-context8.png$$, 502, $$F9h legde tussen de tijdstippen van foto 1 en foto 2 een afstand s af. Deze afstand kan bepaald worden uit:
− het hoogteverschil Δh van 9,21·10⁶ m.
− de afstand Δx, die door de waarnemer is bepaald op 4,38·10⁶ m.

Tussen het maken van foto 1 en foto 2 zat een tijd van 20,0 minuten.$$, 'inline'),
  ('859dc8ab-fb38-43ef-81b9-bd25a958f102', '0ef50c0c-d8c6-43a6-ab55-3ec1daa6f9b2', $$figuur 1 — tabel met vier capsules: isotoop, vervalproducten en halveringstijd$$, $$natuurkunde-havo-2024-i-sarcoide-context1.png$$, 502, $$Een veelvoorkomende tumor bij paarden is een zogenaamde sarcoïde. Dit is een huidtumor. Er bestaan verschillende methodes om deze tumor te behandelen.
Een eerste behandelmethode is bestraling. Hierbij kunnen afgesloten capsules gebruikt worden met radioactieve isotopen die ioniserende straling uitzenden. Deze capsules worden in de tumor geplaatst. In figuur 1 staat een tabel met een aantal capsules met verschillende isotopen die gebruikt kunnen worden.

figuur 1: tabel met de kolommen capsule, isotoop, vervalproducten en t½:
I — Au-198 — β en Hg-198 (niet radioactief) — 3,8 dagen
II — Co-60 — β en Ni-60 (niet radioactief) — 5,3 jaar
III — Cs-137 — β en Ba-137 (niet radioactief) — 30 jaar
IV — Ir-192 — β en Pt-192 (niet radioactief) — 74 dagen$$, 'inline'),
  ('aa122e60-9199-445c-9816-02ccec033c66', '0ef50c0c-d8c6-43a6-ab55-3ec1daa6f9b2', $$één capsule mag blijven zitten, de overige moeten na de bestraling verwijderd worden$$, $$natuurkunde-havo-2024-i-sarcoide-context2.png$$, 502, $$Een van de capsules mag blijven zitten na de behandeling. De overige capsules moeten verwijderd worden wanneer de sarcoïde voldoende is bestraald.$$, 'inline'),
  ('df6f7ff1-371a-4573-aa7c-f7e265dfd74c', '0ef50c0c-d8c6-43a6-ab55-3ec1daa6f9b2', $$behandeling van een sarcoïde met de isotoop Sr-90$$, $$natuurkunde-havo-2024-i-sarcoide-context3.png$$, 502, $$Een sarcoïde kan ook worden behandeld met de isotoop Sr-90.$$, 'inline'),
  ('302afb1d-e069-4ef4-9a6f-5d9f2a4e6c0f', '0ef50c0c-d8c6-43a6-ab55-3ec1daa6f9b2', $$gegevens bestraling: massa 7,9·10⁻⁵ kg, dosis 20 Gy, 2,9 MeV per vervallen kern, activiteit 3,1·10⁶ Bq$$, $$natuurkunde-havo-2024-i-sarcoide-context4.png$$, 502, $$Een bepaalde sarcoïde heeft een massa van 7,9·10⁻⁵ kg en wordt behandeld met Sr-90. Tijdens één bestraling ontvangt deze tumor een dosis van 20 Gy. De energie die per vervallen Sr-90-kern aan de tumor wordt afgegeven is 2,9 MeV. De gemiddelde activiteit tijdens de bestraling is 3,1·10⁶ Bq.$$, 'inline'),
  ('d905dc4a-7182-485c-b0f1-d733fefb1c02', '0ef50c0c-d8c6-43a6-ab55-3ec1daa6f9b2', $$hyperthermie met microgolfstraling van 2,45 GHz; de bron levert 6,2·10²⁵ fotonen per seconde$$, $$natuurkunde-havo-2024-i-sarcoide-context5.png$$, 502, $$Een andere behandelmethode voor een sarcoïde is hyperthermie. Dit is een methode waarbij de tumor vernietigd wordt door hem van buitenaf te verhitten met microgolfstraling met een frequentie van 2,45 GHz. De stralingsbron levert 6,2·10²⁵ fotonen per seconde.$$, 'inline'),
  ('3ef4636f-3076-465c-b919-37c4f248b298', '0ef50c0c-d8c6-43a6-ab55-3ec1daa6f9b2', $$benodigde stralingsenergie 7,2·10² J en daarna nog 30 s nabestralen$$, $$natuurkunde-havo-2024-i-sarcoide-context6.png$$, 502, $$Om een bepaalde sarcoïde op de behandeltemperatuur te brengen moet de stralingsbron 7,2·10² J stralingsenergie leveren. Nadat de behandeltemperatuur is bereikt, wordt de sarcoïde nog 30 s lang bestraald met microgolfstraling om haar op temperatuur te houden.$$, 'inline'),
  ('209c5c24-9031-4abd-958a-66afe559a854', '0ef50c0c-d8c6-43a6-ab55-3ec1daa6f9b2', $$figuur 2 — temperatuur tegen diepte in het weefsel; figuur 3 — doorsnede van de huid van een paard (4,5 mm)$$, $$natuurkunde-havo-2024-i-sarcoide-context7.png$$, 502, $$Bij hyperthermie moet een tumor verhit worden tot minimaal 42 °C. In figuur 2 is de temperatuur die bij deze behandelmethode gehaald kan worden, uitgezet tegen de diepte in het weefsel. In figuur 3 is schematisch de doorsnede van de huid van een paard weergegeven. De huid bestaat uit de opperhuid en de lederhuid. Onder de lederhuid begint het onderhuids weefsel.

figuur 2: grafiek van T in °C (0 en 38 tot 50) tegen de diepte in het weefsel in mm (0 tot 10); de temperatuur daalt van ongeveer 48,5 °C aan het oppervlak tot ongeveer 39 °C op 10 mm diepte en passeert 42 °C bij ongeveer 6 mm.

figuur 3: schematische doorsnede van de huid van een paard met haren, met van boven naar beneden de opperhuid, de lederhuid en het onderhuids weefsel; de dikte van opperhuid en lederhuid samen is met een maatpijl aangegeven als 4,5 mm.$$, 'inline'),
  ('8ba9be66-6400-49e4-a6c2-b354407a6643', '612eecba-d994-4d18-a970-79b925512fc3', $$figuur 1 — trillend zwaard in een kamer met lengte L tussen twee wanden$$, $$natuurkunde-havo-2024-i-infrasone-trillingen-context1.png$$, 502, $$In de jaren 80 deed wetenschapper Vic Tandy een toevallige ontdekking. Hij had een zwaard vastgeklemd om het schoon te maken. Het vrije uiteinde van het zwaard bleek uit zichzelf te trillen. Zie schematisch in figuur 1.

figuur 1: schematisch zijaanzicht van een kamer met links en rechts een wand, een deur en een raam; midden in de kamer staat een klem waarin een zwaard rechtop staat, waarvan het vrije uiteinde heen en weer trilt; de afstand tussen beide wanden is aangegeven met L.$$, 'inline'),
  ('68eab555-b735-4db2-bcb6-71b4db01bf6b', '612eecba-d994-4d18-a970-79b925512fc3', $$trilling het grootst midden in de kamer en nul bij de wanden; infrasoon is lager dan 20 Hz, L = 11,0 m, temperatuur 20 °C$$, $$natuurkunde-havo-2024-i-infrasone-trillingen-context2.png$$, 502, $$Hij verplaatste het zwaard in de kamer. Midden in de kamer trilde het zwaard het hardst. Richting de wanden nam de trilling af, bij de wanden trilde het zwaard niet.

Tandy concludeerde dat infrasone geluidsgolven de oorzaak waren van het trillen van het zwaard. Infrasoon geluid is onhoorbaar voor mensen omdat het een frequentie heeft lager dan 20 Hz. De lengte L van de ruimte is 11,0 m en de temperatuur is 20 °C.$$, 'inline'),
  ('8e509cd8-3216-4bba-b102-8d18677a0ab3', '612eecba-d994-4d18-a970-79b925512fc3', $$uitwerkbijlage vraag 20 — figuur van de kamer met een stippellijn om knopen (K) en buiken (B) in te tekenen$$, $$natuurkunde-havo-2024-i-infrasone-trillingen-uitwerkbijlage-vraag20.png$$, 502, $$Uitwerkbijlage vraag 20: Geef op de stippellijn het patroon aan van knopen (K) en buiken (B) van de grondtoon in de kamer. Daarbij staat de figuur van de kamer met beide wanden, de deur en het raam, met een horizontale stippellijn die van wand tot wand loopt.

Daaronder: Toon met een berekening aan dat de geluidsgolven infrasoon waren. Antwoord: met invulregels.$$, 'uitwerkbijlage'),
  ('7c8342dc-0aba-4a4c-9288-b2f2fa70d783', '612eecba-d994-4d18-a970-79b925512fc3', $$figuur 2 — gebouw van Rijkswaterstaat; figuur 3 — klachten per verdieping weergegeven in grijstinten$$, $$natuurkunde-havo-2024-i-infrasone-trillingen-context3.png$$, 502, $$In 2012 vertoonde een nieuw gebouw van Rijkswaterstaat ongewenste trillingen. Zie figuur 2 voor een foto van dit gebouw. Al snel werd gedacht aan infrasone trillingen. Men startte een onderzoek naar de oorzaak van die trillingen.
Tijdens het onderzoek hebben onderzoekers in beeld gebracht hoeveel klachten er binnen waren gekomen per verdieping. In hun rapport zijn de resultaten weergegeven op de manier van figuur 3.

figuur 2: foto van het kantoorgebouw van Rijkswaterstaat.

figuur 3: schematisch zijaanzicht van het gebouw met de verdiepingen 0 tot en met 23 en bovenop een technische verdieping; de verdiepingen zijn in grijstinten weergegeven die vanaf ongeveer verdieping 7 naar boven toe steeds donkerder worden, met de bovenste verdiepingen bijna zwart.$$, 'inline'),
  ('17a52ad9-cc7e-41d5-8ec1-93c50e0fa28e', '612eecba-d994-4d18-a970-79b925512fc3', $$hoe donkerder de verdieping, hoe groter het percentage klagers; het gaat om een golf in het gebouw$$, $$natuurkunde-havo-2024-i-infrasone-trillingen-context4.png$$, 502, $$Hoe donkerder de verdieping is weergegeven, hoe groter het percentage klagers op deze verdieping.
De onderzoekers hebben geconstateerd dat het gaat om een golf in het gebouw.$$, 'inline'),
  ('c46aaeea-03db-4568-973f-c1cb9304d8e9', '612eecba-d994-4d18-a970-79b925512fc3', $$citaat uit het rapport: melders wijzen de glaswasinstallatie niet aan als mogelijke oorzaak$$, $$natuurkunde-havo-2024-i-infrasone-trillingen-context5.png$$, 502, $$Ook staat in het rapport:

Veel melders zeggen dat de glaswasinstallatie op dat moment in gebruik was, maar wijzen de glaswasinstallatie niet aan als mogelijke oorzaak. De melders kunnen zich niet voorstellen dat deze installatie dergelijke heftige trillingen in het gebouw kan veroorzaken.$$, 'inline'),
  ('efdb3b56-dedc-41de-8a1e-033512e128cb', '612eecba-d994-4d18-a970-79b925512fc3', $$figuur 4 — bureau tussen een luidspreker en een microfoon om de eigenfrequentie te bepalen$$, $$natuurkunde-havo-2024-i-infrasone-trillingen-context6.png$$, 502, $$In het rapport staat verder dat de medewerkers hun bureaus soms heftig op en neer voelden trillen. Tijdens het onderzoek zijn daarom de infrasone eigenfrequenties van de bureaus bepaald.
Een mogelijke methode om deze eigenfrequenties te bepalen is een bureau tussen een luidspreker en een microfoon te plaatsen en de luidspreker steeds een toon met een vaste (infrasone) frequentie te laten uitzenden. Zie schematisch in figuur 4.

figuur 4: schematische tekening van een bureau met daaronder een omhoog gerichte luidspreker en daarboven, op het bureaublad, een microfoon.$$, 'inline'),
  ('91256df0-f288-458e-b682-cbe5567ec9ea', '612eecba-d994-4d18-a970-79b925512fc3', $$uitleg bij figuur 5: gestippelde lijn is de trilling zonder bureau, doorgetrokken lijn met bureau$$, $$natuurkunde-havo-2024-i-infrasone-trillingen-context7.png$$, 502, $$Het signaal dat de microfoon opvangt, wordt vastgelegd in een (u,t)-diagram. In figuur 5 staan vier (u,t)-diagrammen. De gestippelde lijn geeft in elke grafiek de trilling van de microfoon weer als er geen bureau tussen de luidspreker en de microfoon staat. De doorgetrokken streep geeft een mogelijke meetuitkomst als er wel een bureau tussen de luidspreker en de microfoon staat.$$, 'inline'),
  ('e3336936-bb82-43d4-a901-4c7936b2c451', '612eecba-d994-4d18-a970-79b925512fc3', $$figuur 5 — vier (u,t)-diagrammen I, II, III en IV$$, $$natuurkunde-havo-2024-i-infrasone-trillingen-context8.png$$, 502, $$figuur 5: vier (u,t)-diagrammen, genummerd I tot en met IV; in elk diagram staat de gestippelde trilling (zonder bureau) samen met de doorgetrokken trilling (met bureau).
In diagram I heeft de doorgetrokken trilling een veel kleinere periode dan de gestippelde trilling, bij ongeveer dezelfde amplitude.
In diagram II heeft de doorgetrokken trilling een grotere periode dan de gestippelde trilling, bij ongeveer dezelfde amplitude.
In diagram III heeft de doorgetrokken trilling zowel een grotere periode als een grotere amplitude dan de gestippelde trilling.
In diagram IV heeft de doorgetrokken trilling dezelfde periode en dezelfde fase als de gestippelde trilling, maar een duidelijk grotere amplitude.$$, 'inline'),
  ('1edd5a49-c86a-482e-9871-4a647f01b235', '612eecba-d994-4d18-a970-79b925512fc3', $$citaat uit het rapport: de frequentie van de glaswasinstallatie valt samen met de eigenfrequentie van de bureaus (4 Hz)$$, $$natuurkunde-havo-2024-i-infrasone-trillingen-context9.png$$, 502, $$In het rapport staat verder:

Toevalligerwijs valt de frequentie van het trillen van de glaswasinstallatie samen met de eigenfrequentie van de bureaus (4 Hz).$$, 'inline'),
  ('6bd4d0df-81a7-4f2d-a1b6-fe92718a670e', '612eecba-d994-4d18-a970-79b925512fc3', $$glaswasinstallatie als massa-veersysteem: massa 350 kg, veerconstante van de kabels 2,2·10⁵ N m⁻¹$$, $$natuurkunde-havo-2024-i-infrasone-trillingen-context10.png$$, 502, $$De glaswasinstallatie bestaat uit een bak die aan staalkabels hangt, waarin de glazenwassers kunnen staan. De totale massa van bak en glazenwassers is 350 kg. De lange staalkabels kunnen worden beschouwd als een veer. De veerconstante van de kabels samen is 2,2·10⁵ N m⁻¹. De massa van de kabels wordt verwaarloosd.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, image_width, question_text, context_block_ids) values
  ('6811ef80-2ba7-4999-8801-c34883949b56', 'ada6e0f1-7230-4926-af13-3a371f9eb524', 1, '[{"domain": "Beweging en energie", "subdomain": "Energieomzettingen"}]'::jsonb, '["wrijvingsarbeid", "kinetische energie", "wet van behoud van energie", "arbeid berekenen", "wrijvingskracht", "remweg"]'::jsonb, $$Berekenen van een constante wrijvingskracht uit de omzetting van kinetische energie in wrijvingsarbeid.$$, $$natuurkunde-havo-2024-i-schip-uit-koers-vraag1.png$$, 502, $$Toon met behulp van arbeid en kinetische energie aan dat deze waarde voor de wrijvingskracht klopt.$$, array['1e4f0e11-9508-419b-8610-a881b5c1859a', 'd2474d1f-7b36-4a76-be70-3ec462eafdd3']::uuid[]),
  ('ea79b35e-59b7-44dc-adf5-e6cdff1d7555', 'ada6e0f1-7230-4926-af13-3a371f9eb524', 2, '[{"domain": "Beweging en energie", "subdomain": "Energieomzettingen"}]'::jsonb, '["vermogen", "kracht berekenen", "snelheid omrekenen", "arbeid", "wrijvingskracht", "eenheden"]'::jsonb, $$Berekenen van de maximale motorkracht uit vermogen en maximale snelheid en die vergelijken met de wrijvingskracht.$$, $$natuurkunde-havo-2024-i-schip-uit-koers-vraag2.png$$, 502, $$Toon met een berekening aan dat die conclusie klopt.$$, array['1e4f0e11-9508-419b-8610-a881b5c1859a', 'd2474d1f-7b36-4a76-be70-3ec462eafdd3', '0ecb8020-3e61-4029-b72c-aa83834ad5a0']::uuid[]),
  ('03f29fe6-55ba-48ee-b22e-92cbd30b27b9', 'ada6e0f1-7230-4926-af13-3a371f9eb524', 3, '[{"domain": "Beweging en energie", "subdomain": "Kracht en beweging"}]'::jsonb, '["hefboomwet", "momentenwet", "arm", "aangrijpingspunt", "draaipunt", "werklijn", "moment"]'::jsonb, $$Toepassen van de hefboomwet: de armen van twee krachten tekenen en daaruit de krachten vergelijken.$$, $$natuurkunde-havo-2024-i-schip-uit-koers-vraag3.png$$, 502, $$Voer de volgende opdrachten uit:
− Teken in de figuren op de uitwerkbijlage de armen van Fw en Fduwboten.
− Leg met behulp van de hefboomwet uit of om 19.00 uur de totale duwkracht Fduwboten groter was dan Fw, kleiner was dan Fw of even groot was als Fw.$$, array['01214dc2-8664-4750-ab6e-cbfeb8421146', '3465e480-f9a7-4434-8648-47f34a263217', '4f913bef-fb79-4937-be47-39d1cb78ef3c']::uuid[]),
  ('7af8b842-ed59-44c6-bc65-f50fc6636832', 'ada6e0f1-7230-4926-af13-3a371f9eb524', 4, '[{"domain": "Beweging en energie", "subdomain": "Kracht en beweging"}]'::jsonb, '["normaalkracht", "zwaartekracht", "opwaartse kracht", "krachtenevenwicht", "wrijvingskracht", "evenredigheid"]'::jsonb, $$Redeneren hoe zwaartekracht, normaalkracht en de benodigde duwkracht veranderen als de opwaartse kracht op een schip toeneemt.$$, $$natuurkunde-havo-2024-i-schip-uit-koers-vraag4.png$$, 502, $$Omcirkel in de tabel wat er gebeurde tijdens het stijgen van het water.$$, array['fb5863f2-b8e3-483d-9263-b3e96fc5cf16', 'ab9864e9-033e-4342-9e71-4f2db621e633', 'd3886ec0-11c3-4c3a-80bf-e9db8fc5e3b0']::uuid[]),
  ('fb554a45-2883-4480-b11c-9a6780e9093c', 'fb65e46c-caca-42eb-906f-cb680c7eaec8', 5, '[{"domain": "Beweging en energie", "subdomain": "Energieomzettingen"}, {"domain": "Materialen", "subdomain": "Eigenschappen van stoffen en materialen"}]'::jsonb, '["rendement berekenen", "verbrandingswarmte", "soortelijke warmte", "warmte", "energieomzetting", "opwarmen van water"]'::jsonb, $$Berekenen van het rendement waarmee de verbrandingswarmte van hout water opwarmt.$$, $$natuurkunde-havo-2024-i-kampeerbrander-op-hout-vraag5.png$$, 502, $$Toon met een berekening aan of het ontwerp van de jongens daarmee aan de eerste ontwerpeis voldoet.$$, array['48c96e66-f9e5-4d57-bbba-e0df33e622b1', 'dcc3c749-ddc3-49b6-bb20-3819b6714f59', '226f9bdb-b70f-4b1a-8682-0908595ec0bb']::uuid[]),
  ('66f49aab-ccea-4a7e-8b0d-750cf1bd40da', 'fb65e46c-caca-42eb-906f-cb680c7eaec8', 6, '[{"domain": "Materialen", "subdomain": "Eigenschappen van stoffen en materialen"}]'::jsonb, '["thermische geleidbaarheid", "warmtegeleiding", "stofeigenschap", "materiaalkeuze", "warmtetransport"]'::jsonb, $$Kiezen van een materiaal voor een warmtegeleider op grond van de thermische geleidbaarheid.$$, $$natuurkunde-havo-2024-i-kampeerbrander-op-hout-vraag6.png$$, 502, $$Beredeneer met behulp van een stofeigenschap of Jos en Martijn daarom beter een warmtegeleider van aluminium of een warmtegeleider van koper kunnen kiezen.$$, array['9ad68b97-5385-4ba8-9602-0b43d5f21aa4', '4302d215-1e3f-4ba1-9a2a-2659ac8a08ad']::uuid[]),
  ('3e65e21c-76c2-4678-9ae0-d5df19c15c84', 'fb65e46c-caca-42eb-906f-cb680c7eaec8', 7, '[{"domain": "Meten en regelen", "subdomain": "Gebruik van elektriciteit"}, {"domain": "Materialen", "subdomain": "Eigenschappen van stoffen en materialen"}]'::jsonb, '["eenheid afleiden", "evenredigheidsconstante", "spanning", "temperatuurverschil", "formule herleiden"]'::jsonb, $$Afleiden van de eenheid van een evenredigheidsconstante uit een formule die spanning en temperatuurverschil koppelt.$$, $$natuurkunde-havo-2024-i-kampeerbrander-op-hout-vraag7.png$$, 502, $$Leid de eenheid van C af.$$, array['a734c20c-f7f0-4afc-96c4-2eae6133d3f6']::uuid[]),
  ('dba5f146-5856-4200-a90a-51c002d500bb', 'fb65e46c-caca-42eb-906f-cb680c7eaec8', 8, '[{"domain": "Meten en regelen", "subdomain": "Gebruik van elektriciteit"}, {"domain": "Materialen", "subdomain": "Eigenschappen van stoffen en materialen"}]'::jsonb, '["recht evenredig verband", "temperatuurverschil", "spanning berekenen", "evenredigheidsconstante", "verhouding"]'::jsonb, $$Berekenen van het benodigde temperatuurverschil met een recht evenredig verband tussen spanning en temperatuurverschil.$$, $$natuurkunde-havo-2024-i-kampeerbrander-op-hout-vraag8.png$$, 502, $$Bereken het temperatuurverschil dat nodig is om een Upelt van 5,0 V op te wekken.$$, array['a734c20c-f7f0-4afc-96c4-2eae6133d3f6', '46531dd3-f257-48c7-b5fb-d79ecb8de874']::uuid[]),
  ('3ced1826-8d1c-4e3b-b678-112e15cde40f', 'fb65e46c-caca-42eb-906f-cb680c7eaec8', 9, '[{"domain": "Meten en regelen", "subdomain": "Gebruik van elektriciteit"}]'::jsonb, '["serieschakeling", "(I,U)-diagram", "led", "wet van Ohm", "spanningsdeling", "weerstand berekenen", "stroomsterkte aflezen"]'::jsonb, $$Bepalen van de voorschakelweerstand in een serieschakeling met een led met behulp van een (I,U)-diagram.$$, $$natuurkunde-havo-2024-i-kampeerbrander-op-hout-vraag9.png$$, 502, $$Bepaal met behulp van figuur 4 de grootte die de weerstand R₁ moet hebben. Noteer je antwoord in twee significante cijfers.$$, array['1929fd54-76d4-4c5e-bfd1-ded41498ce95', 'fb71a6ad-4b36-4eb5-9b72-a4d9a8bb4fe2']::uuid[]),
  ('692cf6f3-c2ba-449e-be11-eaf4af3bad4d', 'fb65e46c-caca-42eb-906f-cb680c7eaec8', 10, '[{"domain": "Meten en regelen", "subdomain": "Gebruik van elektriciteit"}]'::jsonb, '["parallelschakeling", "stroomdeling", "accucapaciteit", "stroomsterkte", "laadtijd berekenen", "ampère-uur"]'::jsonb, $$Berekenen van de laadtijd van een accu uit de stroomsterkte in een tak van een parallelschakeling en de capaciteit van de accu.$$, $$natuurkunde-havo-2024-i-kampeerbrander-op-hout-vraag10.png$$, 502, $$Voer de volgende opdrachten uit:
− Bereken de tijd die minimaal nodig is om de lege accu volledig op te laden met deze opstelling.
− Leg uit welke conclusie Jos en Martijn moeten trekken over het halen van de vierde ontwerpeis.$$, array['dcc3c749-ddc3-49b6-bb20-3819b6714f59', '15ccb2a3-de50-44bf-8dfb-cdf6718b3602']::uuid[]),
  ('06332dfb-49ac-43a3-8489-5d70a7822d2e', 'a811a389-39db-49d1-a0d7-ad68a868b309', 11, '[{"domain": "Aarde en heelal", "subdomain": "Zonnestelsel en heelal"}, {"domain": "Beweging en energie", "subdomain": "Energieomzettingen"}]'::jsonb, '["cirkelbeweging", "baansnelheid", "baanstraal", "omlooptijd", "kinetische energie", "evenaar", "aardas"]'::jsonb, $$Uitleggen met formules waarom de snelheid van een lanceerplatform bij de evenaar het grootst is en waarom dat brandstof scheelt.$$, $$natuurkunde-havo-2024-i-falcon-heavy-vraag11.png$$, 502, $$Voer de volgende opdrachten uit:
− Leg met behulp van een formule uit het informatieboek uit dat de snelheid vL bij de evenaar het grootst is.
− Leg met behulp van een formule uit het informatieboek uit dat er minder brandstof nodig is als de lanceerplek dicht bij de evenaar ligt.$$, array['658df2b7-d0b9-43c3-a66e-f31bdcbb02bb', '48275c20-b70d-46dd-b1d8-312c78d7d3b2']::uuid[]),
